"use strict";
class KitError extends Error {
  constructor({ code, message, link }) {
    super(message);
    this.name = "KitError";
    this.code = code;
    this.link = link || null;
  }
}

class Sema {
  constructor(n) {
    this.free = n;
    this.queue = [];
  }
  async acquire() {
    if (this.free > 0) {
      this.free--;
      return;
    }
    await new Promise((resolve) => this.queue.push(resolve));
  }
  release() {
    const next = this.queue.shift();
    if (next) next();
    else this.free++;
  }
  nrWaiting() {
    return this.queue.length;
  }
}

function report(err) {
  if (!(err instanceof KitError)) return "not a KitError";
  const own = Object.keys(err).join(",");
  const proto = Object.getPrototypeOf(err).constructor.name;
  const text = typeof err.describe === "function" ? err.describe() : "-";
  return `KitError ${err.code} via ${proto} [${own}] ${text}`;
}

function isError(x) {
  return x instanceof Error;
}

module.exports = { KitError, Sema, report, isError };
